package com.etpms;
import com.etpms.dao.AdminDAO;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;
@WebServlet(urlPatterns={"/admin/employees","/admin/departments"}) public class AdminServlet extends HttpServlet{private final AdminDAO dao=new AdminDAO();protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{try{boolean people=q.getServletPath().endsWith("employees");q.setAttribute("people",people);q.setAttribute("rows",people?dao.employees():dao.departments());q.setAttribute("departments",dao.departments());q.getRequestDispatcher("/WEB-INF/views/admin.jsp").forward(q,p);}catch(Exception e){throw new ServletException(e);}}protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{try{String entity=q.getParameter("entity"),action=q.getParameter("action");if("employee".equals(entity)){if("create".equals(action))dao.createEmployee(q.getParameter("username"),q.getParameter("password"),q.getParameter("role"),q.getParameter("first"),q.getParameter("last"),q.getParameter("email"),q.getParameter("job"),q.getParameter("department"));else if("update".equals(action))dao.updateEmployee(Long.parseLong(q.getParameter("id")),q.getParameter("first"),q.getParameter("last"),q.getParameter("email"),q.getParameter("job"),q.getParameter("department"));else if("delete".equals(action))dao.deleteEmployee(Long.parseLong(q.getParameter("id")));}else{if("create".equals(action))dao.createDepartment(q.getParameter("name"),q.getParameter("description"));else if("delete".equals(action))dao.deleteDepartment(Long.parseLong(q.getParameter("id")));}q.getSession().setAttribute("notice","Changes saved successfully.");}catch(Exception e){q.getSession().setAttribute("error",e.getMessage());}p.sendRedirect(q.getContextPath()+q.getServletPath());}}
